/* ---------- rig: pivot arms at shoulders, parent hands/pen ---------- */
function pivotArm(arm){
  const S=arm.userData.shoulderLocal;
  for(const ch of arm.children){
    if(ch.name.endsWith('-tube')){ ch.geometry.translate(-S.x,-S.y,-S.z); }
    else { ch.position.sub(S); }
  }
  arm.position.copy(S);
}
function reparentKeepWorld(obj,newParent){
  scene.updateMatrixWorld(true);
  const m=obj.matrixWorld.clone();
  newParent.add(obj);
  const pm=newParent.matrixWorld.clone().invert();
  const lm=pm.multiply(m);
  lm.decompose(obj.position,obj.quaternion,obj.scale);
}
