/* ---------- animation tracks (9 samples: 0..1400 ms, wrap to 0 at 1500) ---------- */
const PERIOD=1500, STEP=200, TAU=Math.PI*2;
function kv(vals,t){
  t=((t%PERIOD)+PERIOD)%PERIOD;
  const x=t/STEP, n=vals.length-1;
  const i=Math.min(Math.floor(x),n-1), u=x-i;
  const s=0.5-0.5*Math.cos(Math.PI*u);
  return vals[i]*(1-s)+vals[i+1]*s;
}
