/* ---------- deterministic periodic pose + render ---------- */
function render(t){
  t=((t%PERIOD)+PERIOD)%PERIOD;
  /* one slow belly stroke per 1500 ms loop: hand slides down then back up */
  const w=TAU/PERIOD;
  const down=0.5-0.5*Math.cos(w*t);          /* 0 -> 1 (at 750) -> 0 */
  const pat=Math.sin(w*t), pat2=Math.sin(2*w*t);
